/// Check if any users exist; if not, create the default admin account.
fn run_bootstrap(app_context: &Arc<AppContext>) {
    // Ensure Root entity exists (Qleany requires id=1 Root as ownership trunk)
    let root_exists = match frontend::commands::root_commands::get_root(app_context, &1) {
        Ok(Some(_)) => true,
        _ => false,
    };

    if !root_exists {
        log::info!("Bootstrap: creating Root entity");
        let root_dto = frontend::direct_access::CreateRootDto::default();
        match frontend::commands::root_commands::create_orphan_root(app_context, &root_dto) {
            Ok(root) => log::info!("Bootstrap: Root entity created with id {}", root.id),
            Err(e) => {
                log::error!("Bootstrap: failed to create Root entity: {:?}", e);
                return;
            }
        }
    } else {
        log::info!("Bootstrap: Root entity already exists");
    }

    // Check if users already exist
    let user_list = frontend::commands::user_management_commands::list_users(app_context);
    let user_count = match &user_list {
        Ok(list) => {
            log::info!("Bootstrap: found {} existing users", list.user_ids.len());
            list.user_ids.len()
        }
        Err(e) => {
            log::warn!("Bootstrap: list_users failed ({}), assuming 0 users", e);
            0
        }
    };

    if let Some((username, _password_hash, display_name, role)) =
        inventory_auth::bootstrap::prepare_bootstrap(user_count)
    {
        log::info!(
            "Bootstrap: creating default admin user '{}' with role {:?}",
            username,
            role
        );
        // Use the create_user controller — but it hashes the password internally,
        // so we use the raw "admin" password and let the use case hash it.
        let dto = frontend::user_management::CreateUserDto {
            username,
            password: "Password1".to_string(), // Must be >= 8 chars to pass validation
            display_name,
            role: frontend::user_management::dtos::CreateUserRole::Admin,
            person_id: 0,
        };
        match frontend::commands::user_management_commands::create_user(app_context, &dto) {
            Ok(result) => log::info!("Bootstrap: admin user created with id {}", result.user_id),
            Err(e) => log::error!("Bootstrap: failed to create admin user: {:?}", e),
        }
    } else {
        log::info!("Bootstrap: users already exist, skipping");
    }
}

fn run_slint(app_context: &Arc<AppContext>, sync_engine: Arc<inventory_sync::SyncEngine>) {
    log::info!("Starting InventoryManager Slint UI");
    // Create the event hub client for backend-to-UI event passing
    let event_hub_client = EventHubClient::new(&app_context.event_hub);
    event_hub_client.start(app_context.quit_signal.clone());

    // Create the Slint UI
    let app = App::new().unwrap();

    // Load and apply UI settings
    let ui_settings = UiSettings::load();

    // Initialize translation manager with persisted locale
    let translation_manager = Rc::new(RefCell::new(i18n::TranslationManager::new(&ui_settings.locale)));
    translation_manager.borrow().apply(&app);

    // Wire the change-locale callback for the language switcher
    {
        let tm = Rc::clone(&translation_manager);
        let app_weak = app.as_weak();
        app.global::<TranslationStrings>().on_change_locale(move |index| {
            let locale = match index {
                1 => "fr",
                2 => "ar",
                _ => "en",
            };
            let Some(app) = app_weak.upgrade() else { return };
            tm.borrow_mut().set_locale(locale);
            tm.borrow().apply(&app);

            // Persist the new locale to ui_settings.toml
            let mut settings = UiSettings::load();
            settings.locale = locale.to_string();
            settings.save();
            log::info!("Locale changed to '{}' and persisted", locale);
        });
    }

    app.window()
        .set_size(slint::LogicalSize::new(ui_settings.window_width, ui_settings.window_height));
    if let (Some(x), Some(y)) = (ui_settings.window_x, ui_settings.window_y) {
        app.window()
            .set_position(slint::PhysicalPosition::new(x, y));
    }
    if ui_settings.maximized {
        app.window().set_maximized(true);
    }
    if ui_settings.dark_mode {
        app.global::<AppSettings>().set_dark_mode(true);
        DARK_MODE.store(true, Ordering::Relaxed);
    }

    // Setup stock tracking adapter callbacks
    setup_stock_tracking_callbacks(&app, app_context);

    // Setup budget page adapter callbacks
    setup_budget_callbacks(&app, app_context);

    // Setup sync callbacks
    setup_sync_callbacks(&app, &sync_engine, app_context);

    // Populate SyncPageAdapter from loaded SyncConfig (file-based, no network)
    {
        let config = inventory_sync::SyncConfig::load(std::path::Path::new("sync_config.json"))
            .unwrap_or_default();
        app.global::<SyncPageAdapter>()
            .set_turso_url(slint::SharedString::from(&config.turso_url));
        app.global::<SyncPageAdapter>()
            .set_turso_token(slint::SharedString::from(&config.turso_auth_token));
        app.global::<SyncPageAdapter>()
            .set_auto_sync_enabled(config.auto_sync_enabled);
        app.global::<SyncPageAdapter>()
            .set_sync_interval(config.sync_interval_seconds as i32);
        log::info!("SyncPageAdapter populated from config");
    }

    // Setup CRUD callbacks for all entities
    setup_crud_callbacks(&app, app_context);

    // Populate StockTracking ComboBoxes on page load
    populate_stock_tracking_comboboxes(app_context, &app);

    // Track dark mode changes from the UI Switch
    app.global::<AppSettings>().on_dark_mode_changed(|is_dark| {
        DARK_MODE.store(is_dark, Ordering::Relaxed);
        log::info!("Dark mode changed to: {}", is_dark);
    });

    // ── Auth callback wiring ──────────────────────────────────────────
    {
        let ctx = Arc::clone(app_context);
        let app_weak = app.as_weak();
        app.global::<AppState>().on_login(move |username, password| {
            let Some(app) = app_weak.upgrade() else { return };
            let dto = frontend::authentication::LoginDto {
                username: username.to_string(),
                password: password.to_string(),
            };
            match frontend::commands::authentication_commands::login(&ctx, &dto) {
                Ok(result) if result.success => {
                    app.global::<AppState>().set_is_authenticated(true);
                    app.global::<AppState>()
                        .set_current_user(slint::SharedString::from(&result.display_name));
                    app.global::<AppState>()
                        .set_current_role(slint::SharedString::from(&result.role));
                    app.global::<AppState>()
                        .set_login_error(slint::SharedString::from(""));
                    log::info!("Login successful for user '{}'", username);
                    // Store session token for logout
                    if let Ok(mut token) = SESSION_TOKEN.lock() {
                        *token = result.token.clone();
                    }
                    // Auto-refresh all tables after login
                    refresh_products_table(&ctx, &app);
                    refresh_categories_list(&ctx, &app);
                    refresh_persons_table(&ctx, &app);
                    refresh_deals_table(&ctx, &app);
                    refresh_locations_table(&ctx, &app);
                    refresh_users_table(&ctx, &app);
                    populate_product_comboboxes(&ctx, &app);
                    populate_deal_comboboxes(&ctx, &app);
                    populate_stock_tracking_comboboxes(&ctx, &app);
                    populate_location_manager_combobox(&ctx, &app);
                    // Populate dashboard alerts
                    refresh_dashboard_alerts(&ctx, &app);
                    // Auto-load stock tracking summary
                    app.global::<StockTrackingAdapter>().invoke_load_summary();
                    // Auto-load budget summary and projection
                    app.global::<BudgetPageAdapter>().invoke_load_summary(
                        slint::SharedString::from(""),
                        slint::SharedString::from(""),
                    );
                    app.global::<BudgetPageAdapter>().invoke_load_projection(6);
                }
                Ok(result) => {
                    app.global::<AppState>()
                        .set_login_error(slint::SharedString::from(&result.error_message));
                    log::warn!("Login failed for '{}': {}", username, result.error_message);
                }
                Err(e) => {
                    let msg = format!("{}", e);
                    app.global::<AppState>()
                        .set_login_error(slint::SharedString::from(&msg));
                    log::error!("Login error for '{}': {}", username, e);
                }
            }
        });
    }

    app.window().on_close_requested({
        let ctx = Arc::clone(app_context);
        let app_weak = app.as_weak();

        move || {
            log::info!("Window close requested");

            // Save UI settings
            if let Some(app) = app_weak.upgrade() {
                let maximized = app.window().is_maximized();
                let size = app.window().size();
                let scale = app.window().scale_factor();
                let pos = app.window().position();
                let dark = DARK_MODE.load(Ordering::Relaxed);
                log::info!("Saving settings: size={}x{}, scale={}, dark_mode={}, maximized={}, pos={},{}", 
                    size.width, size.height, scale, dark, maximized, pos.x, pos.y);

                // When maximized, preserve the previous windowed size/position
                // so restoring doesn't produce a full-screen-sized window
                let (w, h, x, y) = if maximized {
                    let prev = UiSettings::load();
                    (prev.window_width, prev.window_height, prev.window_x, prev.window_y)
                } else {
                    (size.width as f32 / scale, size.height as f32 / scale, Some(pos.x), Some(pos.y))
                };

                let settings = UiSettings {
                    window_width: w,
                    window_height: h,
                    dark_mode: dark,
                    maximized,
                    window_x: x,
                    window_y: y,
                    locale: app.global::<TranslationStrings>().get_current_locale().to_string(),
                };
                settings.save();
            }

            ctx.shutdown();
            return slint::CloseRequestResponse::HideWindow;
        }
    });

    // Run the application
    log::info!("Running Slint UI");
    app.run().unwrap();
}

/// Convert a slice of string fields into a single table row of StandardListViewItems.
fn to_table_row(fields: &[&str]) -> slint::ModelRc<slint::StandardListViewItem> {
    let items: Vec<slint::StandardListViewItem> = fields
        .iter()
        .map(|f| {
            let mut item = slint::StandardListViewItem::default();
            item.text = slint::SharedString::from(*f);
            item
        })
        .collect();
    slint::ModelRc::new(slint::VecModel::from(items))
}

