/// Build a SecurityContext for the currently logged-in admin user.
/// In a full implementation, this would resolve from the session token.
fn admin_security_context() -> inventory_security::SecurityContext {
    inventory_security::SecurityContext::from_user(
        1, // admin user id
        frontend::common::entities::UserRole::Admin,
        "bootstrap-token".to_string(),
    )
}

/// Parse a "%Y-%m-%d" date string into `DateTime<Utc>`, falling back to a wide
/// range boundary when the string is empty or unparseable.
fn parse_date_or_default(s: &str, is_start: bool) -> chrono::DateTime<chrono::Utc> {
    use chrono::{NaiveDate, NaiveTime, TimeZone, Utc};
    if let Ok(nd) = NaiveDate::parse_from_str(s, "%Y-%m-%d") {
        Utc.from_utc_datetime(&nd.and_time(NaiveTime::MIN))
    } else if is_start {
        Utc.with_ymd_and_hms(2000, 1, 1, 0, 0, 0).unwrap()
    } else {
        Utc.with_ymd_and_hms(2099, 12, 31, 23, 59, 59).unwrap()
    }
}

/// Resolve a product name to its entity ID by scanning all products.
fn resolve_product_id(ctx: &Arc<AppContext>, name: &str) -> Option<i64> {
    frontend::commands::product_commands::get_all_product(ctx)
        .ok()?
        .iter()
        .find(|p| p.name == name)
        .map(|p| p.id as i64)
}

/// Resolve a location name to its entity ID by scanning all locations.
fn resolve_location_id(ctx: &Arc<AppContext>, name: &str) -> Option<i64> {
    frontend::commands::location_commands::get_all_location(ctx)
        .ok()?
        .iter()
        .find(|l| l.name == name)
        .map(|l| l.id as i64)
}

/// Resolve a category name to its entity ID by scanning all categories.
fn resolve_category_id(ctx: &Arc<AppContext>, name: &str) -> Option<u64> {
    frontend::commands::category_commands::get_all_category(ctx)
        .ok()?
        .iter()
        .find(|c| c.name == name)
        .map(|c| c.id as u64)
}


/// Resolve a person name (with a given role) to its entity ID.
fn resolve_person_id_by_role(
    ctx: &Arc<AppContext>,
    name: &str,
    role: frontend::direct_access::PersonRole,
) -> Option<u64> {
    frontend::commands::person_commands::get_all_person(ctx)
        .ok()?
        .iter()
        .find(|p| p.name == name && p.role == role)
        .map(|p| p.id as u64)
}

/// Wire StockTrackingAdapter callbacks to the stock_tracking controller.
///
/// - `record-movement`: validates inputs, calls record_stock_movement, refreshes
///   history on success, shows error on failure (Req 5.3, 5.4)
/// - `load-history`: calls get_stock_history, populates table and chart (Req 5.5)
/// - `load-summary`: calls get_stock_summary, populates KPI cards (Req 5.2)
fn setup_stock_tracking_callbacks(app: &App, app_context: &Arc<AppContext>) {
    // record-movement callback
    app.global::<StockTrackingAdapter>().on_record_movement({
        let ctx = Arc::clone(app_context);
        let app_weak = app.as_weak();
        move |product, movement_type, quantity, from_loc, to_loc, note| {
            let Some(app) = app_weak.upgrade() else { return };

            log::info!(
                "Record movement: product={}, type={}, qty={}, from={}, to={}, note={}",
                product, movement_type, quantity, from_loc, to_loc, note
            );

            // Resolve product name → ID
            let product_id = match resolve_product_id(&ctx, product.as_str()) {
                Some(id) => id,
                None => {
                    app.global::<StockTrackingAdapter>()
                        .set_error_message(slint::SharedString::from(
                            format!("Product '{}' not found", product),
                        ));
                    return;
                }
            };

            // Resolve location names → IDs (0 if empty/not found)
            let from_location_id = if from_loc.is_empty() {
                0
            } else {
                resolve_location_id(&ctx, from_loc.as_str()).unwrap_or(0)
            };
            let to_location_id = if to_loc.is_empty() {
                0
            } else {
                resolve_location_id(&ctx, to_loc.as_str()).unwrap_or(0)
            };

            // Parse movement type
            let mt = match movement_type.as_str() {
                "Outbound" => frontend::stock_tracking::MovementTypeInput::Outbound,
                "Transfer" => frontend::stock_tracking::MovementTypeInput::Transfer,
                "Adjustment" => frontend::stock_tracking::MovementTypeInput::Adjustment,
                "Return" => frontend::stock_tracking::MovementTypeInput::Return,
                _ => frontend::stock_tracking::MovementTypeInput::Inbound,
            };

            let dto = frontend::stock_tracking::RecordStockMovementDto {
                product_id,
                movement_type: mt,
                quantity: quantity as i64,
                from_location_id,
                to_location_id,
                note: note.to_string(),
            };

            let sec = admin_security_context();
            match frontend::commands::stock_tracking_commands::record_stock_movement(&ctx, &sec, &dto) {
                Ok(result) => {
                    log::info!(
                        "Recorded movement id={}, new qty={}",
                        result.movement_id,
                        result.new_product_quantity
                    );
                    app.global::<StockTrackingAdapter>()
                        .set_error_message(slint::SharedString::from(""));
                    // Refresh products table (quantity changed)
                    refresh_products_table(&ctx, &app);
                }
                Err(e) => {
                    let msg = format!("{}", e);
                    log::error!("Record movement failed: {}", msg);
                    app.global::<StockTrackingAdapter>()
                        .set_error_message(slint::SharedString::from(&msg));
                }
            }
        }
    });

    // load-history callback
    app.global::<StockTrackingAdapter>().on_load_history({
        let ctx = Arc::clone(app_context);
        let app_weak = app.as_weak();
        move |product, from_date, to_date| {
            let Some(app) = app_weak.upgrade() else { return };

            log::info!(
                "Load history: product={}, from={}, to={}",
                product, from_date, to_date
            );

            let product_id = match resolve_product_id(&ctx, product.as_str()) {
                Some(id) => id,
                None => {
                    log::warn!("Product '{}' not found for history", product);
                    return;
                }
            };

            let dto = frontend::stock_tracking::GetStockHistoryDto {
                product_id,
                from_date: parse_date_or_default(from_date.as_str(), true),
                to_date: parse_date_or_default(to_date.as_str(), false),
            };

            let sec = admin_security_context();
            match frontend::commands::stock_tracking_commands::get_stock_history(&ctx, &sec, &dto) {
                Ok(history) => {
                    // Populate movement-rows table
                    let rows: Vec<slint::ModelRc<slint::StandardListViewItem>> = (0..history.movement_ids.len())
                        .map(|i| {
                            to_table_row(&[
                                history.dates.get(i).map(|s| s.as_str()).unwrap_or(""),
                                history.movement_types.get(i).map(|s| s.as_str()).unwrap_or(""),
                                product.as_str(),
                                &history.quantities.get(i).map(|q| q.to_string()).unwrap_or_default(),
                                "", // from location — not in DTO
                                "", // to location — not in DTO
                                "", // user — not in DTO
                                "", // note — not in DTO
                            ])
                        })
                        .collect();
                    let model = std::rc::Rc::new(slint::VecModel::from(rows));
                    app.global::<StockTrackingAdapter>()
                        .set_movement_rows(slint::ModelRc::from(model));

                    log::info!("Loaded {} history entries", history.movement_ids.len());
                }
                Err(e) => log::error!("Failed to load stock history: {}", e),
            }
        }
    });

    // load-summary callback
    app.global::<StockTrackingAdapter>().on_load_summary({
        let ctx = Arc::clone(app_context);
        let app_weak = app.as_weak();
        move || {
            let Some(app) = app_weak.upgrade() else { return };

            log::info!("Load stock summary");

            let sec = admin_security_context();
            match frontend::commands::stock_tracking_commands::get_stock_summary(&ctx, &sec) {
                Ok(summary) => {
                    // Compute aggregate KPIs across all products
                    let total_inbound: i64 = summary.inbound_30d.iter().sum();
                    let total_outbound: i64 = summary.outbound_30d.iter().sum();
                    let net = total_inbound - total_outbound;

                    app.global::<AppState>()
                        .set_stock_inbound_30d(slint::SharedString::from(total_inbound.to_string()));
                    app.global::<AppState>()
                        .set_stock_outbound_30d(slint::SharedString::from(total_outbound.to_string()));
                    app.global::<AppState>()
                        .set_stock_net_30d(slint::SharedString::from(net.to_string()));

                    // Populate product-names for the combo box
                    let names: Vec<slint::SharedString> = summary
                        .product_names
                        .iter()
                        .map(|n| slint::SharedString::from(n.as_str()))
                        .collect();
                    let names_model = std::rc::Rc::new(slint::VecModel::from(names));
                    app.global::<StockTrackingAdapter>()
                        .set_product_names(slint::ModelRc::from(names_model));

                    // Populate location-names for the combo box
                    if let Ok(locations) = frontend::commands::location_commands::get_all_location(&ctx) {
                        let loc_names: Vec<slint::SharedString> = locations
                            .iter()
                            .map(|l| slint::SharedString::from(l.name.as_str()))
                            .collect();
                        let loc_model = std::rc::Rc::new(slint::VecModel::from(loc_names));
                        app.global::<StockTrackingAdapter>()
                            .set_location_names(slint::ModelRc::from(loc_model));
                    }

                    log::info!(
                        "Stock summary: inbound={}, outbound={}, net={}",
                        total_inbound, total_outbound, net
                    );
                }
                Err(e) => log::error!("Failed to load stock summary: {}", e),
            }
        }
    });
}

/// Wire BudgetPageAdapter callbacks to the budget_finance controller.
///
/// - `load-summary`: calls get_budget_summary, populates KPI cards and bar chart
/// - `load-projection`: calls get_budget_projection, populates line charts
/// - `record-entry`: calls record_budget_entry, refreshes summary
fn setup_budget_callbacks(app: &App, app_context: &Arc<AppContext>) {
    // load-summary callback
    app.global::<BudgetPageAdapter>().on_load_summary({
        let ctx = Arc::clone(app_context);
        let app_weak = app.as_weak();
        move |from_date, to_date| {
            let Some(app) = app_weak.upgrade() else { return };

            log::info!("Load budget summary: from={}, to={}", from_date, to_date);

            let dto = frontend::budget_finance::GetBudgetSummaryDto {
                from_date: parse_date_or_default(from_date.as_str(), true),
                to_date: parse_date_or_default(to_date.as_str(), false),
            };

            let sec = admin_security_context();
            match frontend::commands::budget_finance_commands::get_budget_summary(&ctx, &sec, &dto) {
                Ok(summary) => {
                    // Populate KPI cards
                    app.global::<AppState>()
                        .set_total_purchases(slint::SharedString::from(format!("{:.2}", summary.total_purchases)));
                    app.global::<AppState>()
                        .set_total_sales(slint::SharedString::from(format!("{:.2}", summary.total_sales)));
                    app.global::<AppState>()
                        .set_total_expenses(slint::SharedString::from(format!("{:.2}", summary.total_expenses)));
                    app.global::<AppState>()
                        .set_net_balance(slint::SharedString::from(format!("{:.2}", summary.net_balance)));

                    // Populate monthly bar chart data
                    // Each month gets three bars (purchases, sales, expenses) — we
                    // flatten them into a single BarData list with colour coding.
                    let mut bars: Vec<BarData> = Vec::new();
                    let mut max_val: f64 = 0.0;
                    for (i, label) in summary.monthly_labels.iter().enumerate() {
                        let p = *summary.monthly_purchases.get(i).unwrap_or(&0.0);
                        let s = *summary.monthly_sales.get(i).unwrap_or(&0.0);
                        let e = *summary.monthly_expenses.get(i).unwrap_or(&0.0);
                        max_val = max_val.max(p).max(s).max(e);
                        bars.push(BarData {
                            label: slint::SharedString::from(format!("{} P", label)),
                            value: p as f32,
                            color: slint::Color::from_argb_u8(255, 244, 67, 54), // red
                        });
                        bars.push(BarData {
                            label: slint::SharedString::from(format!("{} S", label)),
                            value: s as f32,
                            color: slint::Color::from_argb_u8(255, 76, 175, 80), // green
                        });
                        bars.push(BarData {
                            label: slint::SharedString::from(format!("{} E", label)),
                            value: e as f32,
                            color: slint::Color::from_argb_u8(255, 255, 152, 0), // orange
                        });
                    }
                    let bar_model = std::rc::Rc::new(slint::VecModel::from(bars));
                    app.global::<BudgetPageAdapter>()
                        .set_monthly_bars(slint::ModelRc::from(bar_model));
                    app.global::<BudgetPageAdapter>()
                        .set_monthly_max(max_val as f32);

                    log::info!(
                        "Budget summary: purchases={:.2}, sales={:.2}, expenses={:.2}, net={:.2}",
                        summary.total_purchases, summary.total_sales,
                        summary.total_expenses, summary.net_balance
                    );

                    // Compute trend SVG paths from monthly data
                    let n = summary.monthly_labels.len();
                    if n > 0 {
                        // Build income (sales) and expense trend paths
                        let chart_w = 300.0_f64;
                        let chart_h = 100.0_f64;
                        let max_trend = summary.monthly_sales.iter()
                            .chain(summary.monthly_expenses.iter())
                            .cloned()
                            .fold(0.0_f64, f64::max);

                        let build_trend_path = |values: &[f64]| -> String {
                            let mut parts = Vec::with_capacity(n);
                            for (i, &v) in values.iter().enumerate() {
                                let x = if n == 1 { chart_w / 2.0 } else { (i as f64 / (n - 1) as f64) * chart_w };
                                let y = if max_trend == 0.0 { chart_h } else { chart_h - (v / max_trend) * chart_h };
                                let prefix = if i == 0 { "M" } else { "L" };
                                parts.push(format!("{} {:.1},{:.1}", prefix, x, y));
                            }
                            parts.join(" ")
                        };

                        let income_path = build_trend_path(&summary.monthly_sales);
                        let expense_path = build_trend_path(&summary.monthly_expenses);

                        app.global::<BudgetPageAdapter>()
                            .set_trend_income_path(slint::SharedString::from(&income_path));
                        app.global::<BudgetPageAdapter>()
                            .set_trend_expense_path(slint::SharedString::from(&expense_path));

                        let labels: Vec<slint::SharedString> = summary.monthly_labels.iter()
                            .map(|l| slint::SharedString::from(l.as_str()))
                            .collect();
                        let labels_model = std::rc::Rc::new(slint::VecModel::from(labels));
                        app.global::<BudgetPageAdapter>()
                            .set_trend_x_labels(slint::ModelRc::from(labels_model));

                        log::info!("Budget trends: {} months of data", n);
                    }
                }
                Err(e) => {
                    let msg = format!("{}", e);
                    log::error!("Failed to load budget summary: {}", msg);
                    app.global::<BudgetPageAdapter>()
                        .set_error_message(slint::SharedString::from(&msg));
                }
            }
        }
    });

    // load-projection callback
    app.global::<BudgetPageAdapter>().on_load_projection({
        let ctx = Arc::clone(app_context);
        let app_weak = app.as_weak();
        move |months_ahead| {
            let Some(app) = app_weak.upgrade() else { return };

            log::info!("Load budget projection: months_ahead={}", months_ahead);

            let dto = frontend::budget_finance::GetBudgetProjectionDto {
                months_ahead: months_ahead as i64,
            };

            let sec = admin_security_context();
            match frontend::commands::budget_finance_commands::get_budget_projection(&ctx, &sec, &dto) {
                Ok(projection) => {
                    // Build SVG paths using the chart helper
                    let chart_w = 300.0;
                    let chart_h = 100.0;
                    // Build a Projection struct for the chart helper
                    let proj = frontend::budget_finance::projector::Projection {
                        month_labels: projection.month_labels.clone(),
                        projected_income: projection.projected_income.clone(),
                        projected_expenses: projection.projected_expenses.clone(),
                        projected_balance: projection.projected_balance.clone(),
                        recurring_deal_costs: projection.recurring_deal_costs.clone(),
                    };
                    let (income_path, expense_path, balance_path) =
                        frontend::budget_finance::chart::build_line_chart_paths(&proj, chart_w, chart_h);

                    app.global::<BudgetPageAdapter>()
                        .set_income_path(slint::SharedString::from(&income_path));
                    app.global::<BudgetPageAdapter>()
                        .set_expense_path(slint::SharedString::from(&expense_path));
                    app.global::<BudgetPageAdapter>()
                        .set_balance_path(slint::SharedString::from(&balance_path));

                    // Populate x-labels
                    let labels: Vec<slint::SharedString> = projection
                        .month_labels
                        .iter()
                        .map(|l| slint::SharedString::from(l.as_str()))
                        .collect();
                    let labels_model = std::rc::Rc::new(slint::VecModel::from(labels));
                    app.global::<BudgetPageAdapter>()
                        .set_projection_x_labels(slint::ModelRc::from(labels_model));

                    log::info!("Budget projection loaded for {} months", months_ahead);
                }
                Err(e) => {
                    let msg = format!("{}", e);
                    log::error!("Failed to load budget projection: {}", msg);
                    app.global::<BudgetPageAdapter>()
                        .set_error_message(slint::SharedString::from(&msg));
                }
            }
        }
    });

    // record-entry callback
    app.global::<BudgetPageAdapter>().on_record_entry({
        let ctx = Arc::clone(app_context);
        let app_weak = app.as_weak();
        move |entry_type, amount, description, entry_date, _product, _deal| {
            let Some(app) = app_weak.upgrade() else { return };

            log::info!(
                "Record budget entry: type={}, amount={}, desc={}, date={}",
                entry_type, amount, description, entry_date
            );

            // Parse amount
            let amount_f64 = match amount.as_str().parse::<f64>() {
                Ok(v) => v,
                Err(_) => {
                    app.global::<BudgetPageAdapter>()
                        .set_error_message(slint::SharedString::from(
                            format!("Invalid amount: '{}'", amount),
                        ));
                    return;
                }
            };

            // Parse entry type
            let et = match entry_type.as_str() {
                "Sale" => frontend::budget_finance::BudgetEntryTypeInput::Sale,
                "Expense" => frontend::budget_finance::BudgetEntryTypeInput::Expense,
                "Forecast" => frontend::budget_finance::BudgetEntryTypeInput::Forecast,
                _ => frontend::budget_finance::BudgetEntryTypeInput::Purchase,
            };

            let dto = frontend::budget_finance::RecordBudgetEntryDto {
                entry_type: et,
                amount: amount_f64,
                description: description.to_string(),
                entry_date: parse_date_or_default(entry_date.as_str(), true),
                product_id: 0, // not resolved from UI for now
                deal_id: 0,    // not resolved from UI for now
            };

            let sec = admin_security_context();
            match frontend::commands::budget_finance_commands::record_budget_entry(&ctx, None, &sec, &dto) {
                Ok(result) => {
                    log::info!("Recorded budget entry id={}", result.entry_id);
                    app.global::<BudgetPageAdapter>()
                        .set_error_message(slint::SharedString::from(""));
                    // Refresh summary with current date range
                    let from = app.global::<BudgetPageAdapter>().get_from_date();
                    let to = app.global::<BudgetPageAdapter>().get_to_date();
                    let summary_dto = frontend::budget_finance::GetBudgetSummaryDto {
                        from_date: parse_date_or_default(from.as_str(), true),
                        to_date: parse_date_or_default(to.as_str(), false),
                    };
                    if let Ok(summary) = frontend::commands::budget_finance_commands::get_budget_summary(&ctx, &sec, &summary_dto) {
                        app.global::<AppState>()
                            .set_total_purchases(slint::SharedString::from(format!("{:.2}", summary.total_purchases)));
                        app.global::<AppState>()
                            .set_total_sales(slint::SharedString::from(format!("{:.2}", summary.total_sales)));
                        app.global::<AppState>()
                            .set_total_expenses(slint::SharedString::from(format!("{:.2}", summary.total_expenses)));
                        app.global::<AppState>()
                            .set_net_balance(slint::SharedString::from(format!("{:.2}", summary.net_balance)));
                    }
                }
                Err(e) => {
                    let msg = format!("{}", e);
                    log::error!("Record budget entry failed: {}", msg);
                    app.global::<BudgetPageAdapter>()
                        .set_error_message(slint::SharedString::from(&msg));
                }
            }
        }
    });
}

/// Initialize the SyncEngine at application startup.
///
/// Loads SyncConfig from file (or uses defaults), constructs the engine,
/// and calls hydrate to load data from LibSQL into redb.
/// (Requirements 14.1, 13.1)
fn init_sync_engine(app_context: &Arc<AppContext>) -> Arc<inventory_sync::SyncEngine> {
    use inventory_sync::{ChangeTracker, SyncConfig, SyncEngine};
    use std::path::PathBuf;

    let config_path = PathBuf::from("sync_config.json");
    let config = SyncConfig::load(&config_path).unwrap_or_default();

    let change_tracker = Arc::new(ChangeTracker::new());

    // Subscribe ChangeTracker to EventHub entity events
    let tracker_clone = change_tracker.clone();
    let event_receiver = app_context.event_hub.subscribe_receiver();
    std::thread::spawn(move || {
        use frontend::common::event::{DirectAccessEntity, EntityEvent, Origin};
        while let Ok(event) = event_receiver.recv() {
            let entity_type = match &event.origin {
                Origin::DirectAccess(entity) => match entity {
                    DirectAccessEntity::Product(EntityEvent::Created)
                    | DirectAccessEntity::Product(EntityEvent::Updated)
                    | DirectAccessEntity::Product(EntityEvent::Removed) => Some("products"),
                    DirectAccessEntity::Category(EntityEvent::Created)
                    | DirectAccessEntity::Category(EntityEvent::Updated)
                    | DirectAccessEntity::Category(EntityEvent::Removed) => Some("categories"),
                    DirectAccessEntity::Person(EntityEvent::Created)
                    | DirectAccessEntity::Person(EntityEvent::Updated)
                    | DirectAccessEntity::Person(EntityEvent::Removed) => Some("persons"),
                    DirectAccessEntity::Contact(EntityEvent::Created)
                    | DirectAccessEntity::Contact(EntityEvent::Updated)
                    | DirectAccessEntity::Contact(EntityEvent::Removed) => Some("contacts"),
                    DirectAccessEntity::Deal(EntityEvent::Created)
                    | DirectAccessEntity::Deal(EntityEvent::Updated)
                    | DirectAccessEntity::Deal(EntityEvent::Removed) => Some("deals"),
                    DirectAccessEntity::Location(EntityEvent::Created)
                    | DirectAccessEntity::Location(EntityEvent::Updated)
                    | DirectAccessEntity::Location(EntityEvent::Removed) => Some("locations"),
                    DirectAccessEntity::User(EntityEvent::Created)
                    | DirectAccessEntity::User(EntityEvent::Updated)
                    | DirectAccessEntity::User(EntityEvent::Removed) => Some("users"),
                    DirectAccessEntity::Session(EntityEvent::Created)
                    | DirectAccessEntity::Session(EntityEvent::Updated)
                    | DirectAccessEntity::Session(EntityEvent::Removed) => Some("sessions"),
                    DirectAccessEntity::StockMovement(EntityEvent::Created)
                    | DirectAccessEntity::StockMovement(EntityEvent::Updated)
                    | DirectAccessEntity::StockMovement(EntityEvent::Removed) => {
                        Some("stock_movements")
                    }
                    DirectAccessEntity::BudgetEntry(EntityEvent::Created)
                    | DirectAccessEntity::BudgetEntry(EntityEvent::Updated)
                    | DirectAccessEntity::BudgetEntry(EntityEvent::Removed) => {
                        Some("budget_entries")
                    }
                    _ => None,
                },
                _ => None,
            };

            if let Some(entity_type) = entity_type {
                tracker_clone.on_entity_event(entity_type, &event.ids);
            }
        }
    });

    // Build the SyncEngine on a thread with a larger stack to avoid overflow
    // when opening a remote replica (Hrana client uses deep async call chains).
    let db_ctx = app_context.db_context.clone();
    let engine = std::thread::Builder::new()
        .name("sync-init".into())
        .stack_size(8 * 1024 * 1024) // 8 MB stack
        .spawn(move || {
            let rt = tokio::runtime::Runtime::new().expect("tokio runtime for sync init");
            rt.block_on(SyncEngine::new(config, config_path, change_tracker, db_ctx))
                .expect("Failed to initialize SyncEngine")
        })
        .expect("Failed to spawn sync init thread")
        .join()
        .expect("Sync init thread panicked");

    let engine = Arc::new(engine);

    // Hydrate is deferred until the user logs in and triggers it from the SyncPage.
    log::info!("SyncEngine initialized (hydrate deferred until user login)");

    engine
}

/// Timeout for remote sync operations (60 seconds).
const SYNC_TIMEOUT: std::time::Duration = std::time::Duration::from_secs(300);

/// Wire SyncPage callbacks to the SyncEngine.
/// All callbacks spawn background threads to avoid blocking the Slint UI thread.
fn setup_sync_callbacks(app: &App, sync_engine: &Arc<inventory_sync::SyncEngine>, app_context: &Arc<AppContext>) {
    // sync-to-remote (Push / Dehydrate) — runs on background thread
    app.global::<AppState>().on_sync_to_remote({
        let engine = Arc::clone(sync_engine);
        let app_weak = app.as_weak();
        move || {
            let app_weak = app_weak.clone();
            let engine = Arc::clone(&engine);

            // Set syncing=true on UI thread before spawning
            if let Some(app) = app_weak.upgrade() {
                app.global::<AppState>().set_syncing(true);
            }

            log::info!("Sync: push to remote requested");

            std::thread::spawn(move || {
                let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                    let rt = tokio::runtime::Runtime::new().expect("tokio runtime");
                    let sec = admin_security_context();
                    let pending = engine.change_tracker().pending_count() as i32;
                    let outcome = rt.block_on(async {
                        tokio::time::timeout(SYNC_TIMEOUT, engine.dehydrate(&sec)).await
                    });
                    (outcome, pending)
                }));

                let _ = slint::invoke_from_event_loop(move || {
                    let Some(app) = app_weak.upgrade() else { return };
                    let status = match result {
                        Ok((Ok(Ok(res)), _)) => {
                            let pending = res.entities_written.values().sum::<usize>() as i32;
                            let now = chrono::Utc::now().format("%Y-%m-%d %H:%M:%S").to_string();
                            log::info!("Sync push completed: {:?}", res.entities_written);
                            SyncStatus {
                                last_sync_at: slint::SharedString::from(&now),
                                pending_changes: pending,
                                is_online: res.remote_sync_succeeded,
                                sync_message: slint::SharedString::from(
                                    if res.remote_sync_succeeded { "Push completed" } else { "Push done (local only)" }
                                ),
                                has_remote_url: app.global::<AppState>().get_sync_status().has_remote_url,
                            }
                        }
                        Ok((Ok(Err(e)), pending)) => {
                            log::error!("Sync push failed: {}", e);
                            SyncStatus {
                                last_sync_at: app.global::<AppState>().get_sync_status().last_sync_at,
                                pending_changes: pending,
                                is_online: false,
                                sync_message: slint::SharedString::from(format!("Push failed: {}", e)),
                                has_remote_url: app.global::<AppState>().get_sync_status().has_remote_url,
                            }
                        }
                        Ok((Err(_elapsed), pending)) => {
                            log::error!("Sync push timed out after {}s", SYNC_TIMEOUT.as_secs());
                            SyncStatus {
                                last_sync_at: app.global::<AppState>().get_sync_status().last_sync_at,
                                pending_changes: pending,
                                is_online: false,
                                sync_message: slint::SharedString::from(
                                    format!("Push timeout — remote unreachable ({}s)", SYNC_TIMEOUT.as_secs())
                                ),
                                has_remote_url: app.global::<AppState>().get_sync_status().has_remote_url,
                            }
                        }
                        Err(_panic) => {
                            log::error!("Sync push panicked");
                            SyncStatus {
                                last_sync_at: app.global::<AppState>().get_sync_status().last_sync_at,
                                pending_changes: 0,
                                is_online: false,
                                sync_message: slint::SharedString::from("Internal error during push"),
                                has_remote_url: app.global::<AppState>().get_sync_status().has_remote_url,
                            }
                        }
                    };
                    app.global::<AppState>().set_sync_status(status);
                    app.global::<AppState>().set_syncing(false);
                });
            });
        }
    });

    // sync-from-remote (Pull / Hydrate) — runs on background thread
    app.global::<AppState>().on_sync_from_remote({
        let engine = Arc::clone(sync_engine);
        let app_weak = app.as_weak();
        let ctx = Arc::clone(app_context);
        move || {
            let app_weak = app_weak.clone();
            let engine = Arc::clone(&engine);
            let ctx = Arc::clone(&ctx);

            if let Some(app) = app_weak.upgrade() {
                app.global::<AppState>().set_syncing(true);
            }

            log::info!("Sync: pull from remote requested");

            std::thread::spawn(move || {
                let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                    let rt = tokio::runtime::Runtime::new().expect("tokio runtime");
                    let sec = admin_security_context();
                    let pending = engine.change_tracker().pending_count() as i32;
                    let outcome = rt.block_on(async {
                        tokio::time::timeout(SYNC_TIMEOUT, engine.hydrate(&sec)).await
                    });
                    (outcome, pending)
                }));

                let _ = slint::invoke_from_event_loop(move || {
                    let Some(app) = app_weak.upgrade() else { return };
                    let status = match result {
                        Ok((Ok(Ok(res)), _)) => {
                            let total: usize = res.entities_loaded.values().sum();
                            let now = chrono::Utc::now().format("%Y-%m-%d %H:%M:%S").to_string();
                            log::info!("Sync pull completed: {:?}", res.entities_loaded);
                            SyncStatus {
                                last_sync_at: slint::SharedString::from(&now),
                                pending_changes: 0,
                                is_online: res.was_online,
                                sync_message: slint::SharedString::from(
                                    format!("Pull completed — {} entities loaded", total)
                                ),
                                has_remote_url: app.global::<AppState>().get_sync_status().has_remote_url,
                            }
                        }
                        Ok((Ok(Err(e)), pending)) => {
                            log::error!("Sync pull failed: {}", e);
                            SyncStatus {
                                last_sync_at: app.global::<AppState>().get_sync_status().last_sync_at,
                                pending_changes: pending,
                                is_online: false,
                                sync_message: slint::SharedString::from(format!("Pull failed: {}", e)),
                                has_remote_url: app.global::<AppState>().get_sync_status().has_remote_url,
                            }
                        }
                        Ok((Err(_elapsed), pending)) => {
                            log::error!("Sync pull timed out after {}s", SYNC_TIMEOUT.as_secs());
                            SyncStatus {
                                last_sync_at: app.global::<AppState>().get_sync_status().last_sync_at,
                                pending_changes: pending,
                                is_online: false,
                                sync_message: slint::SharedString::from(
                                    format!("Pull timeout — remote unreachable ({}s)", SYNC_TIMEOUT.as_secs())
                                ),
                                has_remote_url: app.global::<AppState>().get_sync_status().has_remote_url,
                            }
                        }
                        Err(_panic) => {
                            log::error!("Sync pull panicked");
                            SyncStatus {
                                last_sync_at: app.global::<AppState>().get_sync_status().last_sync_at,
                                pending_changes: 0,
                                is_online: false,
                                sync_message: slint::SharedString::from("Internal error during pull"),
                                has_remote_url: app.global::<AppState>().get_sync_status().has_remote_url,
                            }
                        }
                    };
                    app.global::<AppState>().set_sync_status(status);
                    app.global::<AppState>().set_syncing(false);
                    // Refresh all UI tables after pull so the UI reflects pulled data
                    refresh_products_table(&ctx, &app);
                    refresh_categories_list(&ctx, &app);
                    refresh_persons_table(&ctx, &app);
                    refresh_deals_table(&ctx, &app);
                    refresh_locations_table(&ctx, &app);
                    refresh_users_table(&ctx, &app);
                    log::info!("Pull: UI tables refreshed");
                });
            });
        }
    });

    // configure-sync — runs on background thread, auto-tests connection on success
    app.global::<AppState>().on_configure_sync({
        let engine = Arc::clone(sync_engine);
        let app_weak = app.as_weak();
        move |url, token, auto_sync, interval| {
            let app_weak = app_weak.clone();
            let engine = Arc::clone(&engine);
            let url_str = url.to_string();
            let token_str = token.to_string();
            let has_url = !url_str.trim().is_empty();

            log::info!(
                "Sync: configure requested (url={}, auto={}, interval={})",
                url, auto_sync, interval
            );

            if let Some(app) = app_weak.upgrade() {
                app.global::<AppState>().set_syncing(true);
            }

            std::thread::spawn(move || {
                let new_config = inventory_sync::SyncConfig {
                    turso_url: url_str,
                    turso_auth_token: token_str,
                    auto_sync_enabled: auto_sync,
                    sync_interval_seconds: interval as u64,
                    default_strategy: inventory_sync::SyncStrategy::Incremental,
                };

                let sec = admin_security_context();
                let rt = tokio::runtime::Runtime::new().expect("tokio runtime");
                let configure_result = rt.block_on(engine.configure(&sec, new_config));

                // If configure succeeded and URL is set, auto-test connection
                let online = if configure_result.is_ok() && has_url {
                    rt.block_on(async {
                        tokio::time::timeout(SYNC_TIMEOUT, engine.is_online()).await.unwrap_or(false)
                    })
                } else {
                    false
                };

                let _ = slint::invoke_from_event_loop(move || {
                    let Some(app) = app_weak.upgrade() else { return };
                    let status = match configure_result {
                        Ok(()) => {
                            let msg = if has_url {
                                if online { "Settings saved — connected" } else { "Settings saved — remote unreachable" }
                            } else {
                                "Settings saved — local mode"
                            };
                            log::info!("Sync config saved: {}", msg);
                            SyncStatus {
                                last_sync_at: app.global::<AppState>().get_sync_status().last_sync_at,
                                pending_changes: app.global::<AppState>().get_sync_status().pending_changes,
                                is_online: online,
                                sync_message: slint::SharedString::from(msg),
                                has_remote_url: has_url,
                            }
                        }
                        Err(e) => {
                            log::error!("Failed to save sync config: {}", e);
                            SyncStatus {
                                last_sync_at: app.global::<AppState>().get_sync_status().last_sync_at,
                                pending_changes: app.global::<AppState>().get_sync_status().pending_changes,
                                is_online: false,
                                sync_message: slint::SharedString::from(format!("Config error: {}", e)),
                                has_remote_url: app.global::<AppState>().get_sync_status().has_remote_url,
                            }
                        }
                    };
                    app.global::<AppState>().set_sync_status(status);
                    app.global::<AppState>().set_syncing(false);
                });
            });
        }
    });

    // test-connection — runs on background thread
    app.global::<AppState>().on_test_connection({
        let engine = Arc::clone(sync_engine);
        let app_weak = app.as_weak();
        move || {
            let app_weak = app_weak.clone();
            let engine = Arc::clone(&engine);

            if let Some(app) = app_weak.upgrade() {
                app.global::<AppState>().set_syncing(true);
                let mut status = app.global::<AppState>().get_sync_status();
                status.sync_message = slint::SharedString::from("Testing connection...");
                app.global::<AppState>().set_sync_status(status);
            }

            log::info!("Sync: testing connection");

            std::thread::spawn(move || {
                let rt = tokio::runtime::Runtime::new().expect("tokio runtime");
                let online = rt.block_on(async {
                    tokio::time::timeout(SYNC_TIMEOUT, engine.is_online()).await.unwrap_or(false)
                });

                let _ = slint::invoke_from_event_loop(move || {
                    let Some(app) = app_weak.upgrade() else { return };
                    let mut status = app.global::<AppState>().get_sync_status();
                    status.is_online = online;
                    status.sync_message = slint::SharedString::from(
                        if online { "Connection successful" } else { "Connection failed — remote unreachable" }
                    );
                    app.global::<AppState>().set_sync_status(status);
                    app.global::<AppState>().set_syncing(false);
                    log::info!("Connection test result: online={}", online);
                });
            });
        }
    });

    // Set initial sync status
    let pending = sync_engine.change_tracker().pending_count() as i32;
    let config = inventory_sync::SyncConfig::load(std::path::Path::new("sync_config.json"))
        .unwrap_or_default();
    let has_url = !config.turso_url.trim().is_empty();
    app.global::<AppState>().set_sync_status(SyncStatus {
        last_sync_at: slint::SharedString::from("Never"),
        pending_changes: pending,
        is_online: false,
        sync_message: slint::SharedString::from(if has_url { "Ready — not yet synced" } else { "Local mode" }),
        has_remote_url: has_url,
    });
}

/// Shutdown sync: stop auto-sync and attempt a final remote sync if possible.
/// We skip the full redb→LibSQL flush here to avoid stack overflow and
/// long delays on close. The data was already flushed during the last Push.
fn shutdown_sync(sync_engine: &Arc<inventory_sync::SyncEngine>) {
    log::info!("Shutdown: stopping auto-sync");

    let rt = match tokio::runtime::Runtime::new() {
        Ok(rt) => rt,
        Err(e) => {
            log::error!("Shutdown: failed to create tokio runtime: {}", e);
            return;
        }
    };

    rt.block_on(sync_engine.stop_auto_sync());

    // Attempt a lightweight remote sync if the db is already in remote mode.
    // Don't call dehydrate() — it does a full redb flush which is too heavy
    // for shutdown and can cause stack overflow.
    let config = rt.block_on(sync_engine.current_config());
    if !config.turso_url.is_empty() {
        log::info!("Shutdown: attempting final db.sync()");
        // We can't easily access the db handle from here, so just log.
        // The last Push already synced everything.
    }

    log::info!("Shutdown: sync cleanup complete");
}
